package dev.veltraph.client.garden.pests;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Authored pure state/order counterexamples; not executed in this source-only task. */
final class PestInventoryRestorationJournalTest {
    private List<String> before(){var out=new ArrayList<String>();for(int i=0;i<36;i++)out.add("components+count:"+i);return List.copyOf(out);}
    private List<String> after(){var out=new ArrayList<>(before());Collections.swap(out,9,1);return List.copyOf(out);}
    private PestInventoryRestorationJournal.Window<String> open(PestInventoryRestorationJournal<String> j){return j.open(1,100,0,7,9,1,1,0,before(),after(),"empty");}
    private void send(PestInventoryRestorationJournal<String> j,PestInventoryRestorationJournal.Window<String> w){var call=j.beginSend(w,2,0,7,9,1,true,after(),"empty",1,true);j.finishSend(call,3,true,true,after(),"empty",1);}
    private boolean receive(PestInventoryRestorationJournal<String> j,PestInventoryRestorationJournal.Window<String> w,int revision,Map<Integer,String> cells){return j.finishReceive(j.beginReceive(w,4,true),5,true,true,0,revision,cells,after(),"empty",w.selected());}
    private Map<Integer,String> both(){return Map.of(9,after().get(9),1,after().get(1));}
    @Test void localPredictionAloneNeverAcknowledges(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);assertFalse(receive(j,w,8,both()));assertEquals(PestInventoryRestorationJournal.Status.ARMED,w.status());}
    @Test void actualNormalSubmissionAndAppliedBothCells(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertTrue(receive(j,w,8,both()));assertEquals(PestInventoryRestorationJournal.Status.AUTHORITATIVE_AFTER_REQUEST,w.status());}
    @Test void eachChangedSlotRequired(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(receive(j,w,8,Map.of(9,after().get(9))));assertTrue(receive(j,w,9,Map.of(1,after().get(1))));}
    @Test void unrelatedSameItemSlotIsNotRequestedProof(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(receive(j,w,8,Map.of(4,after().get(4))));}
    @Test void completeContentPayloadValidatesAllThirtySix(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);var all=new HashMap<Integer,String>();for(int i=0;i<36;i++)all.put(i,after().get(i));assertTrue(receive(j,w,8,all));}
    @Test void wrongAuthoritativeComponentNeverAccepted(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(receive(j,w,8,Map.of(9,"same name different component")));assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,w.status());}
    @Test void anotherInventoryCellCannotChangeDuringPacket(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);var actual=new ArrayList<>(after());actual.set(30,"foreign");assertFalse(j.finishReceive(j.beginReceive(w,4,true),5,true,true,0,8,both(),actual,"empty",1));}
    @Test void cursorChangeIsNotAcknowledgment(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(j.finishReceive(j.beginReceive(w,4,true),5,true,true,0,8,both(),after(),"carried foreign",1));}
    @Test void selectedSlotChangeWithoutActualOwnedReceiptRefuses(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(j.finishReceive(j.beginReceive(w,4,true),5,true,true,0,8,both(),after(),"empty",0));}
    @Test void actualOwnedSelectionTransitionsExpectedSlot(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertTrue(j.selected(w,4,1,0,true,true,after(),"empty"));assertTrue(receive(j,w,8,both()));assertTrue(j.current(w,6,true,after(),"empty",0));}
    @Test void falseSelectionReceiptCannotAdoptSlot(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(j.selected(w,4,1,0,false,true,after(),"empty"));assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,w.status());}
    @Test void olderNativeBodyReturnCannotSubmitNewWindow(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);var call=j.beginSend(old,2,0,7,9,1,true,after(),"empty",1,true);var newer=open(j);j.finishSend(call,3,true,true,after(),"empty",1);assertEquals(PestInventoryRestorationJournal.Status.ARMED,newer.status());assertTrue(newer.nonce()>old.nonce());}
    @Test void olderNativeBodyThrowCannotRevokeNewWindow(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);var call=j.beginSend(old,2,0,7,9,1,true,after(),"empty",1,true);var newer=open(j);j.finishSend(call,3,false,false,after(),"empty",1);assertEquals(PestInventoryRestorationJournal.Status.ARMED,newer.status());}
    @Test void oldPacketTailCannotClaimReplacementIssue(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);var call=j.beginReceive(old,4,true);var newer=open(j);send(j,newer);assertFalse(j.finishReceive(call,5,true,true,0,8,both(),after(),"empty",1));assertEquals(PestInventoryRestorationJournal.Status.SUBMITTED,newer.status());}
    @Test void packetOutsideSubmittedEntryWindowCannotLaterClaim(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);var early=j.beginReceive(w,2,true);send(j,w);assertFalse(j.finishReceive(early,5,true,true,0,8,both(),after(),"empty",1));}
    @Test void actualNativeThrowLeavesUnknown(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);var call=j.beginSend(w,2,0,7,9,1,true,after(),"empty",1,true);j.finishSend(call,3,false,true,after(),"empty",1);assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,w.status());}
    @Test void interveningWrongSwapInvalidatesOnlyCapturedWindow(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);var receive=j.beginReceive(w,4,true);var wrong=j.beginSend(w,4,0,7,10,1,true,after(),"empty",1,true);j.finishSend(wrong,5,true,true,after(),"empty",1);assertFalse(j.finishReceive(receive,6,true,true,0,8,both(),after(),"empty",1));assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,w.status());}
    @Test void staleRevisionCannotBeFreshServerProof(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(receive(j,w,7,both()));assertFalse(receive(j,w,6,both()));}
    @Test void protocolWrapRemainsUnknown(){var j=new PestInventoryRestorationJournal<String>();var w=j.open(1,100,0,32767,9,1,1,0,before(),after(),"empty");var call=j.beginSend(w,2,0,32767,9,1,true,after(),"empty",1,true);j.finishSend(call,3,true,true,after(),"empty",1);assertFalse(receive(j,w,0,both()));}
    @Test void largeProtocolJumpRefuses(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(receive(j,w,100,both()));}
    @Test void packetRollbackAfterFirstCellRefuses(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(receive(j,w,9,Map.of(9,after().get(9))));assertFalse(receive(j,w,8,Map.of(1,after().get(1))));}
    @Test void deadlineEqualityExpires(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(j.finishReceive(j.beginReceive(w,99,true),100,true,true,0,8,both(),after(),"empty",1));assertEquals(PestInventoryRestorationJournal.Status.EXPIRED,w.status());}
    @Test void monotonicClockRollbackExpires(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertFalse(j.current(w,0,true,after(),"empty",1));assertEquals(PestInventoryRestorationJournal.Status.EXPIRED,w.status());}
    @Test void matchingLocalStateAfterUnknownNeverRevives(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);j.invalidate(w);assertFalse(receive(j,w,8,both()));assertFalse(j.current(w,6,true,after(),"empty",1));}
    @Test void manualSelectionAbaChangesVersionEvenFinalSlotSame(){var v=new PestInventoryRestorationJournal.SlotVersions();long before=v.version();v.begin();v.finish();v.begin();v.finish();assertFalse(v.matches(before));assertEquals(4,v.version());}
    @Test void armDuringInFlightSetterCannotMatch(){var v=new PestInventoryRestorationJournal.SlotVersions();v.begin();assertFalse(v.matches(v.version()));assertEquals(1,v.inFlight());v.finish();assertTrue(v.matches(v.version()));}
    @Test void recursiveSetterScopesBalanceExactly(){var v=new PestInventoryRestorationJournal.SlotVersions();v.begin();v.begin();assertEquals(2,v.inFlight());v.finish();assertFalse(v.matches(v.version()));v.finish();assertEquals(0,v.inFlight());assertTrue(v.matches(4));}
    @Test void setterExceptionStillFinishesAttemptVersion(){var v=new PestInventoryRestorationJournal.SlotVersions();try{v.begin();throw new IllegalStateException();}catch(IllegalStateException expected){}finally{v.finish();}assertTrue(v.matches(2));}
    @Test void rawClickAfterAuthorityInvalidates(){var j=new PestInventoryRestorationJournal<String>();var w=open(j);send(j,w);assertTrue(receive(j,w,8,both()));j.invalidate(w);assertFalse(j.current(w,6,true,after(),"empty",1));}
    @Test void oldRawPacketExitCannotInvalidateReplacement(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);var newer=open(j);j.invalidate(old);assertEquals(PestInventoryRestorationJournal.Status.ARMED,newer.status());}
    @Test void recursiveUnknownCaptureCannotBorrowOuter(){var a=new PestInventoryRestorationJournal.InvocationBoundaries<Object>();Object outer=new Object();var one=a.enter();a.capture(one,outer);var nested=a.enter();try{throw new IllegalStateException();}catch(IllegalStateException expected){assertNull(a.top());}finally{a.exit(nested);}assertSame(outer,a.top());a.exit(one);assertTrue(a.empty());}
    @Test void ineligibleNullTopCannotFallBack(){var a=new PestInventoryRestorationJournal.InvocationBoundaries<Object>();var one=a.enter();a.capture(one,new Object());var two=a.enter();a.capture(two,null);assertNull(a.top());a.exit(two);assertNotNull(a.top());}
    @Test void recursiveNewTokenHasItsOwnExactBoundary(){var a=new PestInventoryRestorationJournal.InvocationBoundaries<Object>();Object old=new Object(),newer=new Object();var one=a.enter();a.capture(one,old);var two=a.enter();a.capture(two,newer);a.exit(one);assertSame(newer,a.top());a.exit(two);assertSame(old,a.top());a.exit(one);assertTrue(a.empty());}
    @Test void qualificationThrowRetainsInvalidationOnlyOldEntry(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);var stack=new PestInventoryRestorationJournal.InvocationBoundaries<PestInventoryRestorationJournal.Window<String>>();var b=stack.enter();stack.capture(b,old);try{throw new IllegalStateException("source getter failed");}catch(IllegalStateException expected){j.invalidate(stack.top());}finally{stack.exit(b);}assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,old.status());assertFalse(receive(j,old,8,both()));}
    @Test void failedQualificationNeverRevokesReplacementWindow(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);var stack=new PestInventoryRestorationJournal.InvocationBoundaries<PestInventoryRestorationJournal.Window<String>>();var b=stack.enter();stack.capture(b,old);var newer=open(j);j.invalidate(stack.top());assertEquals(PestInventoryRestorationJournal.Status.ARMED,newer.status());stack.exit(b);}
    @Test void nestedUnknownEntryInvalidatesItsOwnWindowOnly(){var j=new PestInventoryRestorationJournal<String>();var outer=open(j);var stack=new PestInventoryRestorationJournal.InvocationBoundaries<PestInventoryRestorationJournal.Window<String>>();var a=stack.enter();stack.capture(a,outer);var inner=open(j);var b=stack.enter();stack.capture(b,inner);j.invalidate(stack.top());assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,inner.status());stack.exit(b);assertSame(outer,stack.top());stack.exit(a);}
    @Test void invalidationOnlyCaptureCannotSubmitOrAcknowledge(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);j.invalidate(old);assertFalse(receive(j,old,8,both()));assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,old.status());}
    @Test void capturedRawDisturbanceAfterReceiveRefusesAuthority(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);assertTrue(receive(j,old,8,both()));var captured=old;j.invalidate(captured);assertFalse(j.current(old,6,true,after(),"empty",1));}
    @Test void exactNativeSelectionRequiresOneSetterCompletionAndPacket(){var e=new PestInventoryRestorationJournal.SelectionEffects();assertTrue(e.beforeSetter());e.setter();assertFalse(e.afterSetter());e.completed(true);assertTrue(e.afterSetter());assertFalse(e.exact());e.packet(true);assertTrue(e.exact());}
    @Test void recursiveManualSetterCannotBorrowOwnSelection(){var e=new PestInventoryRestorationJournal.SelectionEffects();e.setter();e.completed(true);e.setter();e.completed(true);e.packet(true);assertFalse(e.exact());}
    @Test void unrelatedOrDuplicateCarriedPacketCannotQualify(){var e=new PestInventoryRestorationJournal.SelectionEffects();e.setter();e.completed(true);e.packet(true);e.packet(true);assertFalse(e.exact());}
    @Test void setterThrowNeverBecomesOwnedSelection(){var e=new PestInventoryRestorationJournal.SelectionEffects();e.setter();e.completed(false);e.packet(true);assertFalse(e.exact());}
    @Test void oldPacketExitOrFailedSourceCannotRenewSelection(){var e=new PestInventoryRestorationJournal.SelectionEffects();e.setter();e.completed(true);e.packet(false);assertFalse(e.exact());e.packet(true);assertFalse(e.exact());}
    @Test void manualVersionAbaAndScopedReceiptCountsAreSeparate(){var v=new PestInventoryRestorationJournal.SlotVersions();long old=v.version();v.begin();v.finish();v.begin();v.finish();var e=new PestInventoryRestorationJournal.SelectionEffects();e.setter();e.completed(true);e.packet(true);assertTrue(e.exact());assertFalse(v.matches(old+2));}
    @Test void rawEntryRefusesBeforeNestedNativeSendConsumer(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);assertTrue(receive(j,old,8,both()));j.invalidate(old);Runnable original=()->assertFalse(j.current(old,6,true,after(),"empty",1));original.run();assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,old.status());}
    @Test void unrelatedQualifiedSendEntryCannotDelayInvalidationUntilReturn(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);assertTrue(receive(j,old,8,both()));var outgoing=j.beginSend(old,6,0,7,9,1,true,after(),"empty",1,false);assertFalse(j.current(old,7,true,after(),"empty",1));j.finishSend(outgoing,8,true,true,after(),"empty",1);assertEquals(PestInventoryRestorationJournal.Status.UNKNOWN,old.status());}
    @Test void rawEntryAndOldExitPreserveReplacementIssue(){var j=new PestInventoryRestorationJournal<String>();var old=open(j);send(j,old);j.invalidate(old);var newer=open(j);send(j,newer);j.invalidate(old);assertEquals(PestInventoryRestorationJournal.Status.SUBMITTED,newer.status());}
    @Test void serverThreadInventoryNeverPassesClientGate(){Object inventory=new Object();var v=new PestInventoryRestorationJournal.SlotVersions();if(PestInventoryRestorationJournal.clientInventory(false,inventory,inventory))v.begin();assertEquals(0,v.version());assertEquals(0,v.inFlight());}
    @Test void foreignPlayerInventoryNeverPassesClientGate(){Object client=new Object(),server=new Object();var v=new PestInventoryRestorationJournal.SlotVersions();if(PestInventoryRestorationJournal.clientInventory(true,client,server))v.begin();assertEquals(0,v.version());assertEquals(0,v.inFlight());}
    @Test void actualClientInventoryGatePreservesRealSetterVersion(){Object inventory=new Object();var v=new PestInventoryRestorationJournal.SlotVersions();if(PestInventoryRestorationJournal.clientInventory(true,inventory,inventory)){v.begin();v.finish();}assertTrue(v.matches(2));}
}
